// Build facts for the process page (SPEC-showcase decision 4): generated by npm run showcase:facts and committed. Commits
// and CI runs come from the development history in the private archive (SPEC-public-release W3); tests from this repository.

export type BuildFacts = {
  generated_at: string;
  pipeline: string;
  policy: string;
  commits: { total: number; first: string; last: string; byType: Record<string, number>; byDay: Record<string, number> };
  tests: { unit: number; unitFiles: number; e2e: number; sqlContracts: number };
  ci: CiSummary;
  llm: { calls: number; costUsd: number; first: string | null } | null;
};

const TYPE = /^(\w+)(\([^)]*\))?!?:/;

export function commitTypes(subjects: string[]): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const s of subjects) {
    const type = s.match(TYPE)?.[1] ?? "other";
    counts[type] = (counts[type] ?? 0) + 1;
  }
  return counts;
}

// The calendar day of each commit as its author saw it (the date in the ISO timestamp's own offset), in date order.
export function commitsByDay(isoDates: string[]): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const d of [...isoDates].sort((a, b) => a.slice(0, 10).localeCompare(b.slice(0, 10)))) {
    counts[d.slice(0, 10)] = (counts[d.slice(0, 10)] ?? 0) + 1;
  }
  return counts;
}

export type CiRun = { conclusion: string; headBranch: string; createdAt: string };
export type CiSummary = { runs: number; success: number; failure: number; failedProof: number; failedMain: number;
  mainFixedWithinMinutes: number | null; mainUnfixed: number };

// Failures on the proof branch were deliberate (SPEC-evals criterion 2: a broken change must fail the gate). A failure on
// main counts as fixed by the next successful run on main; the slowest fix is reported.
export function ciSummary(runs: CiRun[], proofBranch = "proof/eval-gate"): CiSummary {
  const main = runs.filter((r) => r.headBranch === "main").sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  let slowest: number | null = null;
  let unfixed = 0;
  main.forEach((r, i) => {
    if (r.conclusion !== "failure") return;
    const fix = main.slice(i + 1).find((x) => x.conclusion === "success");
    if (!fix) { unfixed += 1; return; }
    const minutes = Math.ceil((Date.parse(fix.createdAt) - Date.parse(r.createdAt)) / 60_000);
    slowest = Math.max(slowest ?? 0, minutes);
  });
  return {
    runs: runs.length, success: runs.filter((r) => r.conclusion === "success").length,
    failure: runs.filter((r) => r.conclusion === "failure").length,
    failedProof: runs.filter((r) => r.conclusion === "failure" && r.headBranch === proofBranch).length,
    failedMain: main.filter((r) => r.conclusion === "failure").length, mainFixedWithinMinutes: slowest, mainUnfixed: unfixed,
  };
}
